-- Coaching tools: Derby PKA Pad Work Syllabus 25-26 (from the Word file). Skips it if already added.
insert into coaching_tools (title, description, category, kind, body)
select 'Derby PKA Pad Work Syllabus 25-26', 'Focus pad combinations for every belt, Red to Black Belt 1st Dan', 'Pad work', 'page', '<p>Focus pad combinations for each belt. <mark>Highlighted</mark> combinations are the ones highlighted in the syllabus (numbers 9 and 10 at each belt, and the Black Belt full set).</p><h2>Red Belt</h2><p><b>Sequences (numbers):</b> 1-2</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>1,2,RFK</td><td></td></tr><tr><td>2</td><td>1,1,2,RFK</td><td></td></tr><tr><td>3</td><td>1,2,1,RFK</td><td>Isolated, Laces</td></tr><tr><td>4</td><td>1,RRK</td><td>FK, Ball of the foot</td></tr><tr><td>5</td><td>1,2,RRK</td><td></td></tr><tr><td>6</td><td>1,1,2,RRK</td><td></td></tr><tr><td>7</td><td>Parry, 1,2,1,RRK</td><td></td></tr><tr><td>8</td><td>High guard<br>2, 1,RRK</td><td>Outside, use palm</td></tr><tr><td>9</td><td><mark>1,2, High guard<br>1,2,RFK</mark></td><td></td></tr><tr><td>10</td><td><mark>1,2,High guard, 1,2,1,2 RRK</mark></td><td></td></tr></tbody></table><h2>Yellow Belt</h2><p><b>Sequences (numbers):</b> 1-4</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>1,1,2,3,RRK,1</td><td></td></tr><tr><td>2</td><td>1, Parry, 1,2<br>Shield, 2,3 RRK</td><td>3 with rotation</td></tr><tr><td>3</td><td>12(Parry, Sheild, Cover) 1,2,3,RRK</td><td></td></tr><tr><td>4</td><td>1,Parry, Shield, 2,3 RRK</td><td></td></tr><tr><td>5</td><td>1&gt;,2,3, RRK</td><td></td></tr><tr><td>6</td><td>1,&lt;,1,2,&lt;,1,2,3,&lt;,1,2,3,RRK     (&lt;or &gt;)</td><td></td></tr><tr><td>7</td><td>1,2,&gt;,&lt;,1,2,3,RRK</td><td></td></tr><tr><td>8</td><td>121&gt;&lt; 1,2,3,RRK</td><td></td></tr><tr><td>9</td><td><mark>parry,1,2, &gt; 2,3,2 shield, 2,3,RRK<br>LFK</mark></td><td></td></tr><tr><td>10</td><td><mark>1,1,2 &gt; 2,3, RRK - shield, cover, shield<br>2,3,RRK</mark></td><td></td></tr></tbody></table><h2>Orange Belt</h2><p><b>Sequences (numbers):</b> 1-6</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Parry,1,2,1,LRK,1,2,RRK</td><td></td></tr><tr><td>2</td><td>LRK,parry,1,2,3,3,RRK</td><td></td></tr><tr><td>3</td><td>LRK,2,&gt;,1,2,Shield,2,3,RRK,1</td><td></td></tr><tr><td>4</td><td>Catch,1,2,3, L Shield, 3,2,3, RRK. 3</td><td></td></tr><tr><td>5</td><td>B1,b2,1,2,Parry,Shield,Cover,323 RRK</td><td></td></tr><tr><td>6</td><td>B2,3,2 LRK  - 123 turn RRK</td><td></td></tr><tr><td>7</td><td>123, RRK,1b2, LRK</td><td></td></tr><tr><td>8</td><td>parry 12 LRK – b1,b2,3,RRK</td><td></td></tr><tr><td>9</td><td><mark>Lead elbow block, 232LRK<br>1,2,1 Slip,2,3,2 LRK,1</mark></td><td></td></tr><tr><td>10</td><td><mark>LRK - Catch,1,2,Slip, 5,2,LRK,1<br>1,b2, LRK</mark></td><td></td></tr></tbody></table><h2>Green Belt</h2><p><b>Sequences (numbers):</b> 1-8</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>Inside parry(rk) ,2,1,2,Lead chop, 1,2,LRK</td><td></td></tr><tr><td>2</td><td>Lead side kick, lead chop, 1,2,3,2, ?RRK</td><td></td></tr><tr><td>3</td><td>Push away-Lead chop 2-6,3,2 turn RRK</td><td></td></tr><tr><td>4</td><td>Lead Scissor, L Chop  1,2,1 slip 3,2, LRK</td><td></td></tr><tr><td>5</td><td>&lt;, 3,turn,RRK 1,2,5,2,3,Rear scissor</td><td></td></tr><tr><td>6</td><td>Push away 3,2, LRK, control</td><td></td></tr><tr><td>7</td><td>Turn out 2,3,2 – RRK, rear chop</td><td></td></tr><tr><td>8</td><td>Turn in 3,3,2,3- LRK(h)-rear chop</td><td></td></tr><tr><td>9</td><td><mark>Lead elbow block, 2,3,2, LRK<br>Closed side step 1,2,5,2, LRK, crash 1,2 LRK</mark></td><td></td></tr><tr><td>10</td><td><mark>Lead elbow block, 2,3,2, RRK<br>Open side step 2,5,2,3, RRK, crash 2,3 RRK</mark></td><td></td></tr></tbody></table><h2>Blue Belt</h2><p><b>Sequences (numbers):</b> 1-10</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>1,2,3,roll,3,2,roll 2,3,R chop</td><td></td></tr><tr><td>2</td><td>1,2,roll,2,3,roll,3,2, L chop</td><td></td></tr><tr><td>3</td><td>1, slip 5,2, LRK</td><td></td></tr><tr><td>4</td><td>1,slip,6,2,3,RRK (h)</td><td></td></tr><tr><td>5</td><td>1, b2, 3, LRK (h) RRK (b)</td><td></td></tr><tr><td>6</td><td>LHK-RK – drop 2,B3,3,2,RRK(h)</td><td></td></tr><tr><td>7</td><td>lay back,2,roll,2, LRK(B), LRK(H)</td><td></td></tr><tr><td>8</td><td>1,2,5,slip, 3,2,3,R chop</td><td></td></tr><tr><td>9</td><td><mark>L sweep, 121, slip, Lscrew,2,LRK<br>roll turn 2,5,2, RRK, `LHK</mark></td><td></td></tr><tr><td>10</td><td><mark>121212, slip, bump step –<br>3,3,2,3 Rear sweep, L Chop</mark></td><td></td></tr></tbody></table><h2>Purple Belt</h2><p><b>Sequences (numbers):</b> 1-12</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>B1, LRK (h),12,bouble LRK</td><td></td></tr><tr><td>2</td><td>LSK, L Chop LSK, cut RK (any leg)</td><td></td></tr><tr><td>3</td><td>Check 3,2-push 12,vip</td><td></td></tr><tr><td>4</td><td>Slip,6,LRK (h),skip LRK 1,1,2</td><td></td></tr><tr><td>5</td><td>Slip, 5, RRK (h), skip RRK, 3,3,2</td><td></td></tr><tr><td>6</td><td>1,Slip,b6,2,3 skip&gt;, LRK</td><td></td></tr><tr><td>7</td><td>Push 2-2,5,2, L Sweep</td><td></td></tr><tr><td>8</td><td>Lead clash, LRK, 1,2-6,3,2,turn, RRK</td><td></td></tr><tr><td>9</td><td><mark>TSK,12RRK , check 3, push 1,2<br>LSK (short), 1, slip turn in</mark></td><td></td></tr><tr><td>10</td><td><mark>B1, Over2, Roll,2, LRK<br>1 b2,LRK,THK,drop2</mark></td><td></td></tr></tbody></table><h2>Brown Belt</h2><p><b>Sequences (numbers):</b> 1-14</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>LSK (b), LRK (h) parry 1,2 Roll LRK (h)</td><td></td></tr><tr><td>2</td><td>Clash, L parry,3,2,LRK, 1,2,3 Roll RRK (h)</td><td></td></tr><tr><td>3</td><td>Fake THK, skip side, skip chop, push 2</td><td></td></tr><tr><td>4</td><td>Clash 12, Switch back 3,2, LRK (h)</td><td></td></tr><tr><td>5</td><td>LSK, LSK, Scoop, 3,2,3 – back kick</td><td></td></tr><tr><td>6</td><td>Scoop, 2,3,2 – RRK(h), return, THK, LRK</td><td></td></tr><tr><td>7</td><td>Double LSK,12,L sweep,12, THK</td><td></td></tr><tr><td>8</td><td>L sweep,632, 360</td><td></td></tr><tr><td>9</td><td><mark>1, pull 2, Roll away, THK, L shield 3,2,3 roll b4, check 3, RRK,360</mark></td><td></td></tr><tr><td>10</td><td><mark>Inside parry(rk) ,2,1,2,Lead chop, 1,2,LRK<br>(slide) chop, (fade out) LSK, push 3,2, back kick</mark></td><td></td></tr></tbody></table><h2>Black Belt 1st Dan</h2><p><b>Sequences (numbers):</b> 1-16</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td>B1, Over2, LRK, spinning side Kick</td><td></td></tr><tr><td>2</td><td>LRK, b cover,6x,1,2,back kick</td><td></td></tr><tr><td>3</td><td>Cover,5x,2,1,2,step through, THK</td><td></td></tr><tr><td>4</td><td>Spin sweep, turn out, 323,vip, LRK (b), 360</td><td></td></tr><tr><td>5</td><td>L arm bar, 2,1,360</td><td></td></tr><tr><td>6</td><td>L guard, push 12, lead sweep,2,5,2,&gt;,360</td><td></td></tr><tr><td>7</td><td>Step though rear sweep, turn out,2, draw back RK</td><td></td></tr><tr><td>8</td><td>Set, Step through L sweep, turn in, 2, push away Jump THK</td><td></td></tr><tr><td>9</td><td><mark>Cross block, 4 cross punch, away, check back kick, 4 x45 doubles, check hook</mark></td><td></td></tr><tr><td>10</td><td><mark>1,2, back kick, turn, LRK, switch back<br>1,2, LRK, RRK</mark></td><td></td></tr></tbody></table><h3>Full set (16 combinations)</h3><p><b>Sequences (numbers):</b> 1-16</p><table><thead><tr><th>#</th><th>Focus pads</th><th>Notes</th></tr></thead><tbody><tr><td>1</td><td><mark>High guard, 1,2,RRK</mark></td><td></td></tr><tr><td>2</td><td><mark>1,2,1,2 RFK</mark></td><td></td></tr><tr><td>3</td><td><mark>LFK,1,2-parry, shield, 2,3 RRK</mark></td><td></td></tr><tr><td>4</td><td><mark>1,2 &gt;2,3, cover, shield,2,3,2 RRK</mark></td><td></td></tr><tr><td>5</td><td><mark>LRK,1,2, Slip, 2,3,2 LRK</mark></td><td></td></tr><tr><td>6</td><td><mark>Catch,1,2,Slip, 5,2, LRK</mark></td><td></td></tr><tr><td>7</td><td><mark>Closed side step 1,2,5,2, LRK</mark></td><td></td></tr><tr><td>8</td><td><mark>Open side step 2,5,2,3, RRK</mark></td><td></td></tr><tr><td>9</td><td><mark>121,Lay, slip, 5,2,LRK, roll turn 2,5,2 LHK</mark></td><td></td></tr><tr><td>10</td><td><mark>1212,Lay, slip, turn -3,3,2,3 L Chop</mark></td><td></td></tr><tr><td>11</td><td><mark>LSK (short), 1, slip turn in, TSK, check 3, push 1,2</mark></td><td></td></tr><tr><td>12</td><td><mark>B1, Over2, &gt; THK , 1,2,3,3 RRK</mark></td><td></td></tr><tr><td>13</td><td><mark>1, pull 2, Roll away, THK, L shield 3,2,3 roll b4, check 3, RRK,360</mark></td><td></td></tr><tr><td>14</td><td><mark>(slide) chop, (fade out) LSK, push 3,2, back kick</mark></td><td></td></tr><tr><td>15</td><td><mark>Set,4 cross punch, away, check back kick, 4 x45 doubles,check hook</mark></td><td></td></tr><tr><td>16</td><td><mark>1,2, back kick, turn, LRK, switch back, 1,2, LRK, RRK</mark></td><td></td></tr></tbody></table><h2>Other topics</h2><p>Headings at the end of the syllabus (no combinations written under them yet):</p><ul><li>Over control</li><li>Hook clash</li><li>Sweeps</li><li>Controls</li><li>Lay, slip, turn</li></ul>'
where not exists (select 1 from coaching_tools where title = 'Derby PKA Pad Work Syllabus 25-26');

select title, category, kind, length(body) as size from coaching_tools where category = 'Pad work';
